.controls-card { padding: 12px 16px; }

.filter-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.filter-row-secondary {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

